using System;
using System.IO;
using System.Reflection;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor.SceneManagement;
public static class CameraVisibilityReview {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 [Serializable]public class Trial{public int trial,width,height;public float distance,beforeShellWidth,afterShellWidth,beforeCameraSize,afterCameraSize;public string before,after;public bool bodyInsideFrame;}
 [Serializable]public class Record{public string status="PASS_FIXED_CAMERA_COMPARISON";public string scope="Actual Unity native same pose, camera, light and query state. Minimum-size parameter only changes. Viewport is stage area, not a physical phone.";public Trial[] trials;}
 static void Call(object g,string n,params object[] a)=>g.GetType().GetMethod(n,F).Invoke(g,a);
 static object Get(object g,string n)=>g.GetType().GetField(n,F).GetValue(g);
 static void Render(Camera c,int w,int h,string path){var old=c.targetTexture;var rt=RenderTexture.GetTemporary(w,h,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);var active=RenderTexture.active;c.targetTexture=rt;c.Render();RenderTexture.active=rt;var t=new Texture2D(w,h,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,w,h),0,0);t.Apply();File.WriteAllBytes(path,t.EncodeToJPG(92));UnityEngine.Object.DestroyImmediate(t);c.targetTexture=old;RenderTexture.active=active;RenderTexture.ReleaseTemporary(rt);}
 static Rect Bounds(Camera c,Renderer r,int width,int height){var b=r.bounds;var min=new Vector2(float.PositiveInfinity,float.PositiveInfinity);var max=new Vector2(float.NegativeInfinity,float.NegativeInfinity);for(int i=0;i<8;i++){var p=c.WorldToViewportPoint(b.center+Vector3.Scale(b.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1)));min=Vector2.Min(min,new Vector2(p.x*width,p.y*height));max=Vector2.Max(max,new Vector2(p.x*width,p.y*height));}return Rect.MinMaxRect(min.x,min.y,max.x,max.y);}
 public static void Run(){Directory.CreateDirectory("../evidence/camera-comparison");typeof(CrabModel).GetField("materials",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,null);((System.Collections.IDictionary)typeof(CrabModel).GetField("arenaMaterials",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null)).Clear();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var g=new GameObject("CrabActionGame").AddComponent<CrabActionGame>();g.crabShader=Shader.Find("CustomCrabBattle/ChitinR3");g.groundShader=Shader.Find("Standard");g.aiEnabled=false;g.Initialize();g.Begin("");var camera=g.ReviewCamera;var p=(CrabModel)Get(Get(g,"player"),"model");Renderer shell=null;foreach(var r in p.Root.GetComponentsInChildren<MeshRenderer>())if(r.name.StartsWith("CarapacePart")){shell=r;break;}if(!shell)throw new Exception("Visible carapace not found");var list=new List<Trial>();
  foreach(var viewport in new[]{new Vector2Int(320,504),new Vector2Int(390,780),new Vector2Int(544,342)})foreach(float distance in new[]{2.15f,8f})for(int n=1;n<=3;n++){g.ReviewPlace(Vector3.zero,new Vector3(0,0,distance));camera.aspect=(float)viewport.x/viewport.y;var t=new Trial{trial=n,width=viewport.x,height=viewport.y,distance=distance};
   typeof(CrabActionGame).GetField("combatMinimumSize",F).SetValue(g,6.6f);Call(g,"UpdateCamera",1f,true);var before=Bounds(camera,shell,viewport.x,viewport.y);t.beforeShellWidth=before.width;t.beforeCameraSize=camera.orthographicSize;t.before="camera-comparison/"+viewport.x+"-"+distance.ToString("F2",System.Globalization.CultureInfo.InvariantCulture)+"-"+n+"-before.jpg";Render(camera,viewport.x,viewport.y,"../evidence/"+t.before);
   typeof(CrabActionGame).GetField("combatMinimumSize",F).SetValue(g,5.2f);Call(g,"UpdateCamera",1f,true);var after=Bounds(camera,shell,viewport.x,viewport.y);t.afterShellWidth=after.width;t.afterCameraSize=camera.orthographicSize;t.after="camera-comparison/"+viewport.x+"-"+distance.ToString("F2",System.Globalization.CultureInfo.InvariantCulture)+"-"+n+"-after.jpg";Render(camera,viewport.x,viewport.y,"../evidence/"+t.after);t.bodyInsideFrame=after.xMin>=0&&after.yMin>=0&&after.xMax<=viewport.x&&after.yMax<=viewport.y;
   if(!t.bodyInsideFrame||t.afterShellWidth<t.beforeShellWidth||distance==2.15f&&t.afterShellWidth/t.beforeShellWidth<1.26f||distance==8&&Mathf.Abs(t.beforeCameraSize-t.afterCameraSize)>.0001f)throw new Exception("Camera bounds/scale comparison failed");list.Add(t);
  }File.WriteAllText("../evidence/camera-visibility-review.json",JsonUtility.ToJson(new Record{trials=list.ToArray()},true));
 }
}
